function NexlabPrivacyCheckNotice({status,onRetry,onSignOut,compact=false}){
  if(!status?.check_error || (compact && !status.verified))return null;
  const title=compact?"Não foi possível atualizar a verificação de privacidade":"Não foi possível verificar a privacidade";
  const message=status.check_error==="service"
    ?"O serviço de privacidade não está disponível. Tente novamente. Se o problema continuar, peça ao administrador para verificar o serviço."
    :status.check_error==="session"
      ?"Sua sessão precisa ser verificada novamente. Tente novamente ou saia e entre na sua conta."
      :"A conexão ou o serviço está temporariamente indisponível. Verifique sua conexão e tente novamente.";
  const content=o.jsxs("section",{
    className:compact?"mx-4 mt-3 md:mx-6 xl:mx-8 shrink-0 rounded-2xl border border-orange-200 bg-orange-50 p-4 text-slate-700":"w-full max-w-xl rounded-3xl border border-slate-200 bg-white p-6 md:p-8 shadow-lg",
    role:compact?"status":"alert","aria-busy":!!status.refreshing,"data-nexlab-privacy-notice":compact?"background":"initial",
    children:[o.jsx(compact?"h2":"h1",{className:"text-lg font-bold text-blue-dark",children:title}),
      o.jsx("p",{className:"mt-2 text-sm leading-relaxed",children:message}),
      o.jsxs("div",{className:"mt-4 flex flex-wrap gap-3",children:[
        o.jsx("button",{type:"button",onClick:onRetry,disabled:!!status.refreshing,className:"px-5 py-3 rounded-xl bg-orange-500 text-white text-sm font-bold disabled:opacity-60",children:status.refreshing?"Verificando…":"Tentar novamente"}),
        !compact&&o.jsx("button",{type:"button",onClick:onSignOut,className:"px-5 py-3 rounded-xl border border-slate-200 text-sm font-bold text-slate-600",children:"Sair da conta"})]})]
  });
  return compact?content:o.jsx("div",{className:"min-h-screen nexlab-bg flex items-center justify-center p-4",children:content});
}

